using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using CircuitoStudio;
class DrawingDxfTests {
 static int n;static void Check(bool good,string label){n++;if(!good)throw new Exception(label);}static void Reject(Action action,string label){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
 [STAThread]static int Main(){try{var root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-dxf");Directory.CreateDirectory(root);
  foreach(string version in new[]{"R12","R2010"}){string file=Path.Combine(root,"externo-"+version+".dxf");var input=DrawingDxf.Inspect(file);Check(input.CompletePreview&&input.Entities.Count==3,"independent "+version+" supported types");var line=input.Entities.First(x=>x.Type=="LINE");Check(line.X==-12.25&&line.Y==3.5&&line.X2==47&&line.Y2==-8.125,"independent line coordinates");var circle=input.Entities.First(x=>x.Type=="CIRCLE");Check(circle.X==10&&circle.Y==20&&circle.Radius==4.75,"independent circle coordinates");var text=input.Entities.First(x=>x.Type=="TEXT");Check(text.Text=="Iluminação Ω 漢字"&&text.Rotation==30,"independent Unicode text and rotation");var destination=Path.Combine(root,"roundtrip-"+version+".dxf");input.SaveOriginal(destination);input.SaveOriginal(destination);Check(File.ReadAllBytes(file).SequenceEqual(File.ReadAllBytes(destination)),"byte-exact independent roundtrip");Check(File.Exists(destination+".bak"),"roundtrip backup");}
  var additional=DrawingDxf.Inspect(Path.Combine(root,"externo-entidades-adicionais.dxf"));Check(!additional.CompletePreview&&additional.Unsupported.ContainsKey("LWPOLYLINE")&&additional.Unsupported.Count==2,"unsupported and special text reported");additional.SaveOriginal(Path.Combine(root,"preservado-adicionais.dxf"));Check(File.ReadAllBytes(Path.Combine(root,"externo-entidades-adicionais.dxf")).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"preservado-adicionais.dxf"))),"unsupported objects preserved in exact export");
  var project=Project.CreateSample();project.Name="Projeto Ω";var board=project.Boards[0];var circuit=board.Circuits[0];circuit.DiagramLabel="Luz Ω 漢字";circuit.DiagramX=123.25;circuit.DiagramY=145.5;var memory=EngineeringReport.Memory(project,Engineering.Analyze(project));project.Save(Path.Combine(root,"origem.circuito"));DrawingDxf.Save(DrawingDxf.Unifilar(project,board),Path.Combine(root,"unifilar.dxf"));DiagramSvg.Save(project,board,Path.Combine(root,"unifilar.svg"));var read=DrawingDxf.Inspect(Path.Combine(root,"unifilar.dxf"));Check(read.CompletePreview,"own unifilar readable");Check(read.Entities.Any(x=>x.Type=="TEXT"&&x.Text=="Luz Ω 漢字"),"unifilar full label Unicode");Check(read.Entities.Any(x=>x.Type=="CIRCLE"&&x.X==123.25&&x.Y==-(145.5+105)),"persisted symbol position");
  int symbol=0;foreach(DiagramSymbol type in Enum.GetValues(typeof(DiagramSymbol))){circuit.DrawingSymbol=type;DrawingDxf.Save(DrawingDxf.Unifilar(project,board),Path.Combine(root,"simbolo-"+symbol+".dxf"));DiagramSvg.Save(project,board,Path.Combine(root,"simbolo-"+symbol+".svg"));symbol++;}circuit.DrawingSymbol=DiagramSymbol.Automatico;
  EnclosureCatalog.Apply(project,board,EnclosureCatalog.ReferenceCatalog()[1]);foreach(var c in board.Circuits)EnclosureCatalog.ApplyFootprint(project,board,c,new DinFootprint{WidthModules=6,Equipment="Conjunto QA",Reference="Largura sintética QA",DataVersion="QA1",Conditions="Ensaio geométrico",CoversAccessories=true},0,0);DrawingDxf.Save(DrawingDxf.Frontal(project,board),Path.Combine(root,"frontal.dxf"));var frontal=DrawingDxf.Inspect(Path.Combine(root,"frontal.dxf"));Check(frontal.Entities.Count(x=>x.Layer=="RAILS")==2,"real front rail count");Check(frontal.Entities.Any(x=>x.Type=="TEXT"&&x.Text.Contains("1SPE007717F0510")),"front reference in drawing");board.Circuits[1].DinColumn=1;board.Circuits[1].DinRow=1;circuit.DinColumn=1;circuit.DinRow=1;DrawingDxf.Save(DrawingDxf.Frontal(project,board),Path.Combine(root,"frontal-pendente.dxf"));Check(DrawingDxf.Inspect(Path.Combine(root,"frontal-pendente.dxf")).Entities.Any(x=>x.Type=="TEXT"&&x.Text.StartsWith("PENDENTE:")),"invalid occupancy cannot export approval");Enclosures.AutoArrange(board);
  var simple=new DxfDrawing();simple.Text(0,0,2,@"Literal \U+0041 %%d Ω","TEXT");DrawingDxf.Save(simple,Path.Combine(root,"literal.dxf"));Check(DrawingDxf.Inspect(Path.Combine(root,"literal.dxf")).Entities[0].Text==@"Literal \U+0041 %%d Ω","literal escapes not interpreted recursively");string preserved=Path.Combine(root,"preservar.dxf");File.WriteAllText(preserved,"ORIGINAL");simple.Entities[0].Text="quebra\ninjetada";Reject(()=>DrawingDxf.Save(simple,preserved),"line injection rejected");Check(File.ReadAllText(preserved)=="ORIGINAL","invalid export preserves previous file");simple.Entities[0].Text=new string('Ω',100);Reject(()=>DrawingDxf.Save(simple,preserved),"encoded R12 text limit enforced");simple.Entities[0].Text=Char.ConvertFromUtf32(0x1F600);Reject(()=>DrawingDxf.Save(simple,preserved),"supplementary Unicode explicitly rejected by R12 writer");simple.Entities[0].Text="ok";simple.Entities[0].X=Double.NaN;Reject(()=>DrawingDxf.Save(simple,preserved),"NaN coordinate rejected");simple.Entities[0].X=0;simple.Entities[0].Height=0;Reject(()=>DrawingDxf.Save(simple,preserved),"zero text height rejected");
  string good=File.ReadAllText(Path.Combine(root,"unifilar.dxf"));string bad=Path.Combine(root,"invalido.dxf");File.WriteAllText(bad,good.Replace("0\r\nEOF\r\n",""));Reject(()=>DrawingDxf.Inspect(bad),"truncation rejected");File.WriteAllText(bad,good+"1\r\n");Reject(()=>DrawingDxf.Inspect(bad),"incomplete pair rejected");File.WriteAllText(bad,good.Replace("AC1009","AC9999"));Reject(()=>DrawingDxf.Inspect(bad),"unknown version rejected");File.WriteAllText(bad,"AutoCAD Binary DXF\0");Reject(()=>DrawingDxf.Inspect(bad),"binary DXF rejected");Reject(()=>DrawingDxf.Inspect(Path.Combine(root,"sem-amostra.amb")),"AMB explicitly unsupported");File.WriteAllText(bad,good.Replace("10\r\n26\r\n","10\r\nNaN\r\n"));Reject(()=>DrawingDxf.Inspect(bad),"import NaN rejected");
  project.Save(Path.Combine(root,"antes-interface.circuito"));using(var form=new DrawingDxfForm(project,board)){form.LoadDrawing(Path.Combine(root,"unifilar.dxf"));if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(5,5);form.Show();Application.DoEvents();form.Refresh();form.Update();Check(form.PreviewError==null,form.PreviewError??"preview paint succeeds");using(var bmp=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bmp))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bmp.Save(Path.Combine(root,"dxf-previa.png"));}form.Hide();}Reject(()=>form.LoadDrawing(Path.Combine(root,"sem.amb")),"UI refuses AMB");}project.Save(Path.Combine(root,"depois-interface.circuito"));Check(File.ReadAllBytes(Path.Combine(root,"antes-interface.circuito")).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"depois-interface.circuito"))),"inspection does not mutate project");Check(Engineering.Analyze(project).Circuits.Count>0,"electrical engine still works");Console.WriteLine("PASS: "+n+" drawing DXF assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
